function media(p){return p.thumbnail||p.image||''}
function build(records,sources){const groups=new Map(),srcMap=new Map(sources.map(s=>[s.id,s]));for(const p of records){if(!p?.url||!p.name||/^\s*(?:(?:EUR|USD|CNY|RMB|GBP)\s*)?[\d\s.,€$¥￥£|/–-]+(?:\s*(?:EUR|USD|CNY|RMB|GBP))?\s*$/i.test(p.name))continue;let key=p.productKey||identity(p.url),g=groups.get(key);if(!g){g={key,name:p.name,brand:Object.keys(preferred).find(b=>preferred[b].test(p.name))||p.brand||'Weitere',category:category(p.name),offers:[],names:[],references:[],images:[],cached:false};groups.set(key,g)}if(!g.names.includes(p.name))g.names.push(p.name);g.cached||=!!p.thumbnail;const image=media(p);if(image&&!g.images.includes(image))g.images.push(image);if(!g.images.length&&p.image)g.images.push(p.image);if(!g.offers.some(o=>o.url===p.url&&o.euro===p.euro&&o.source===p.source))g.offers.push({...p,sourceInfo:srcMap.get(p.source),shop:shop(p)});if(!g.references.some(o=>o.source===p.source&&o.sourceUrl===p.sourceUrl&&o.location===p.location))g.references.push({source:p.source,name:srcMap.get(p.source)?.name||p.source,sourceUrl:p.sourceUrl||srcMap.get(p.source)?.url||'',location:p.location});if(p.thumbnail){g.images=g.images.filter(x=>x!==p.thumbnail);g.images.unshift(p.thumbnail)}}for(const g of groups.values()){g.mine=g.names.some(n=>Object.values(preferred).some(rx=>rx.test(n)));g.price=Math.min(...g.offers.filter(p=>Number.isFinite(p.euro)).map(p=>p.euro));if(!Number.isFinite(g.price))g.price=null;g.offers.sort((a,b)=>(a.euro??Infinity)-(b.euro??Infinity));}return [...groups.values()]}
function sourceDuplicates(records,sources){const sets=new Map();for(const p of records){if(!sets.has(p.source))sets.set(p.source,new Set());sets.get(p.source).add(p.productKey||identity(p.url))}const seen=new Map(),duplicates=[];for(const s of sources){let set=sets.get(s.id);if(!set||set.size<15)continue;let signature=[...set].sort().join('|');if(seen.has(signature))duplicates.push({name:s.name,of:seen.get(signature),count:set.size});else seen.set(signature,s.name)}const names=new Map();for(const p of records){let n=p.name.toLowerCase().replace(/\s+/g,' ').trim();if(n.length<=12)continue;if(!names.has(p.source))names.set(p.source,new Set());names.get(p.source).add(n)}const similar=[];for(let i=0;i<sources.length;i++)for(let j=i+1;j<sources.length;j++){let a=names.get(sources[i].id),b=names.get(sources[j].id);if(!a||!b)continue;let overlap=[...a].filter(n=>b.has(n)).length,ratio=overlap/Math.min(a.size,b.size);if(overlap>=100&&ratio>.85)similar.push({name:sources[i].name,of:sources[j].name,count:overlap,ratio,kind:'similar'})}return duplicates.concat(similar.sort((a,b)=>b.ratio-a.ratio).slice(0,6))}
