function haulTotals(haul){let goods=0,unknown=0,quantity=0;for(const item of Object.values(haul.items||{})){const q=Math.min(99,Math.max(1,Math.floor(Number(item.quantity)||1)));quantity+=q;if(Number.isFinite(item.offer?.euro)&&item.offer.euro>=0)goods+=item.offer.euro*q;else unknown+=q}const cost=value=>{if(value===''||value==null)return null;const n=Number(String(value).replace(',','.'));return Number.isFinite(n)&&n>=0?n:null};const costs=Object.fromEntries(['shipping','packing','domestic','fees','taxes'].map(k=>[k,cost(haul[k])]));goods=Math.round(goods*100)/100;return {goods,unknown,quantity,...costs,total:haul.costsStale||unknown||Object.values(costs).some(v=>v===null)?null:Math.round((goods+Object.values(costs).reduce((a,b)=>a+b,0))*100)/100}}
